// Converts the Markdown the app sends into Notion blocks.
// Returns one item per 100-block batch, because Notion accepts at most
// 100 children per request and a real plan exceeds that.
const markdown = $('StudySync webhook').first().json.body.payload.markdown ?? '';

function markdownToBatches(markdown) {
  const LIMIT = 1900; // Notion caps a single rich_text value at 2000 chars.

  // Parses **bold** and `code` into Notion rich_text runs so the page does
  // not render literal asterisks and backticks.
  function richText(text) {
    if (!text) return [];
    const runs = [];
    const pattern = /(\*\*([^*]+)\*\*|`([^`]+)`)/g;
    let last = 0;
    let m;
    while ((m = pattern.exec(text)) !== null) {
      if (m.index > last) {
        runs.push({ type: "text", text: { content: text.slice(last, m.index) } });
      }
      if (m[2] !== undefined) {
        runs.push({ type: "text", text: { content: m[2] }, annotations: { bold: true } });
      } else {
        runs.push({ type: "text", text: { content: m[3] }, annotations: { code: true } });
      }
      last = m.index + m[0].length;
    }
    if (last < text.length) {
      runs.push({ type: "text", text: { content: text.slice(last) } });
    }
    // Split any run that is still over the per-value limit.
    const safe = [];
    for (const run of runs) {
      const content = run.text.content;
      if (content.length <= LIMIT) {
        safe.push(run);
        continue;
      }
      for (let i = 0; i < content.length; i += LIMIT) {
        safe.push({ ...run, text: { content: content.slice(i, i + LIMIT) } });
      }
    }
    return safe.slice(0, 100); // Notion caps rich_text runs per block at 100.
  }

  function toBlock(line) {
    const trimmed = line.trimEnd();
    if (!trimmed.trim()) return null; // Skip blanks; they only burn block budget.

    let m;
    if ((m = /^###\s+(.*)$/.exec(trimmed))) {
      return { object: "block", type: "heading_3", heading_3: { rich_text: richText(m[1]) } };
    }
    if ((m = /^##\s+(.*)$/.exec(trimmed))) {
      return { object: "block", type: "heading_2", heading_2: { rich_text: richText(m[1]) } };
    }
    if ((m = /^#\s+(.*)$/.exec(trimmed))) {
      return { object: "block", type: "heading_1", heading_1: { rich_text: richText(m[1]) } };
    }
    if ((m = /^-\s+\[\s*\]\s+(.*)$/.exec(trimmed))) {
      return {
        object: "block",
        type: "to_do",
        to_do: { rich_text: richText(m[1]), checked: false },
      };
    }
    if ((m = /^[-*]\s+(.*)$/.exec(trimmed))) {
      return {
        object: "block",
        type: "bulleted_list_item",
        bulleted_list_item: { rich_text: richText(m[1]) },
      };
    }
    if ((m = /^>\s+(.*)$/.exec(trimmed))) {
      return { object: "block", type: "quote", quote: { rich_text: richText(m[1]) } };
    }
    return { object: "block", type: "paragraph", paragraph: { rich_text: richText(trimmed) } };
  }

  const blocks = markdown.split("\n").map(toBlock).filter(Boolean);

  // Notion accepts at most 100 children per request, so emit one item per
  // batch. The HTTP node downstream runs once per item, appending in order.
  const batches = [];
  for (let i = 0; i < blocks.length; i += 100) {
    batches.push({ json: { blocks: blocks.slice(i, i + 100) } });
  }
  return batches.length > 0 ? batches : [{ json: { blocks: [] } }];
}

return markdownToBatches(markdown);

// Fan the digest out into one item per action item.
// Read from the webhook, not $input: this node runs after Create session
// page, so its input is the Notion page, which has no actionItems.
const payload = $('StudySync webhook').first().json.body.payload;
const tasks = payload.actionItems || [];
return tasks.map((t) => ({ json: t }));
